function parseTitles(xmlStr) {
  if (!xmlStr || typeof xmlStr !== 'string') return [];
  const cdataMatches = [...xmlStr.matchAll(/<item>[\s\S]*?<title><!\[CDATA\[(.*?)\]\]><\/title>/g)];
  if (cdataMatches.length > 0) return cdataMatches.slice(0, 2).map(m => m[1].trim());
  const plain = [...xmlStr.matchAll(/<item>[\s\S]*?<title>(.*?)<\/title>/g)];
  return plain.slice(0, 2).map(m => m[1].replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').trim());
}

